from taf.fdsw.rc.schemas.base import SchemaField, SchemaObject
from taf.fdsw.rc.schemas.FDSW18A.autoconnection import ManagementPlaneParameters, CertificateServerParameters


class PnpProtocolParameters(SchemaObject):
    selected_protocol = SchemaField(name="selectedProtocol")

    def __init__(self, selected_protocol):
        self.selected_protocol = selected_protocol
        super(PnpProtocolParameters, self).__init__()


class Steps(SchemaObject):
    label = SchemaField(name="label")
    status = SchemaField(name="status")
    status_details = SchemaField(name="statusDetails")

    def __init__(self, label, status, status_details):
        self.label = label
        self.status = status
        self.status_details = status_details
        super(Steps, self).__init__()


class Connection(SchemaObject):
    label = SchemaField(name="label")
    status = SchemaField(name="status")
    reasoning = SchemaField(name="reasoning")
    steps = SchemaField(name="steps", klass=Steps, many=True)

    def __init__(self, label, status, reasoning, steps):
        self.label = label
        self.status = status
        self.reasoning = reasoning
        self.steps = steps
        super(Connection, self).__init__()


class Configuration(SchemaObject):
    label = SchemaField(name="label")
    status = SchemaField(name="status")
    mode = SchemaField(name="mode")
    steps = SchemaField(name="steps", klass=Steps, many=True)

    def __init__(self, label, status, mode, steps):
        self.label = label
        self.status = status
        self.mode = mode
        self.steps = steps
        super(Configuration, self).__init__()


class PnpStatus(SchemaObject):
    connection = SchemaField(name="connection", klass=Connection)
    configuration = SchemaField(name="configuration", klass=Configuration)

    def __init__(self, connection, configuration):
        self.connection = connection
        self.configuration = configuration
        super(PnpStatus, self).__init__()


class AutoConnection(SchemaObject):
    pnp_status = SchemaField(name="pnpStatus", klass=PnpStatus)
    management_plane_parameters = SchemaField(name="managementPlaneParameters", klass=ManagementPlaneParameters)
    certificate_server_parameters = SchemaField(name="certificateServerParameters", klass=CertificateServerParameters)
    pnp_protocol_parameters = SchemaField(name="pnpProtocolParameters", klass=PnpProtocolParameters)

    def __init__(self, pnp_status, management_plane_parameters, pnp_protocol_parameters, certificate_server_parameters):
        super(AutoConnection, self).__init__()
        self.pnp_status = pnp_status
        self.management_plane_parameters = management_plane_parameters
        self.pnp_protocol_parameters = pnp_protocol_parameters
        self.certificate_server_parameters = certificate_server_parameters
